-- Build tracker items. Number 016 leaves 015 for the in-flight fills dedupe migration.
-- The migrator applies this id when 015 is absent.
-- steps is a JSON checklist. Percent is the share of steps marked done.
-- Live dates are noon America/Chicago. A second run inserts 0 rows.

CREATE TABLE IF NOT EXISTS build_items (
  id text PRIMARY KEY,
  title text NOT NULL,
  node text NOT NULL CHECK (node IN ('crypto', 'ai-stocks', 'fitness', 'finance', 'fight-desk', 'platform', 'youtube')),
  pr_number integer,
  status text NOT NULL CHECK (status IN ('live', 'in_progress', 'queued', 'blocked')),
  steps jsonb NOT NULL,
  next_step text,
  sort_order integer NOT NULL,
  updated_at timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS build_items_node_sort_idx ON build_items (node, sort_order);

ON CONFLICT (id) DO NOTHING;
